# -*- coding: utf-8 -*-
"""Cedere: go, give way, come next, and the cessare branch."""
import json
from pathlib import Path
from lesson_authoring import entry as E
BASE=Path(__file__).resolve().parents[1];OUT=BASE/'.cache/batch200/drafts/rewrite_spec'
H=[['拉丁 cēdere；分词词干 cess-','走、离开；让步、让出']]
SU=H+[['拉丁 sub- + cēdere → succēdere','接着来、接替；事情进展顺利']]
SUCCESS=SU+[['拉丁 successus → 英语 success','结果、进展 → 好结果、成功']]
PRO=H+[['拉丁 prō- + cēdere → prōcēdere','朝前走、推进']]
PROCEED=PRO+[['古法语 proceder 及拉丁词 → 中古英语 proceden → 英语 proceed','继续向前、接着做']]
PROCEDURE=PRO+[['法语 procédure → 英语 procedure','做事推进的步骤与程序']]
PROCESS=PRO+[['拉丁 prōcessus → 古法语 proces；亦有直接拉丁来源','前进、进程；诉讼过程'],['中古英语 proces → 英语 process','过程、程序；后来也作处理、加工的动词']]
PROCESSION=PRO+[['拉丁 prōcessiō → 古法语 procession / pourciession 与早期英语借词','向前行进 → 宗教或仪式队列'],['中古英语 processioun → 英语 procession','成队行进；行进的队伍']]
PRE=H+[['拉丁 prae- + cēdere → praecēdere','走在前面、先发生']]
PRECEDE=PRE+[['中古法语 précéder → 英语 precede','在……之前']]
PRECEDENT=PRE+[['拉丁 praecēdēns / praecēdent- → 法语 precedent；亦可直接借入','走在前面的、在先的'],['英语 precedent','先前的实例 → 可供后来参照的先例']]
RE=H+[['拉丁 re- + cēdere → recēdere','往后走、退去']]
AC=H+[['拉丁 ad- + cēdere → accēdere','走近、进入；加入、答应']]
SE=H+[['拉丁 sē- + cēdere → sēcēdere','分开走、退出']]
CO=H+[['拉丁 con- + cēdere → concēdere','充分让出 → 允许、承认、让步']]
CEASE=H+[['拉丁反复动词 cessāre → 法语 cesser','退开、停下来 → 停止'],['中古英语 cesen / cessen → 英语 cease','停止、终止']]
W=[
E('success','/səkˈses/','成功；成功的人或事','事情往下发展，最后落到了想要的结果上。','借拉丁 successus，接 succēdere“接着来、进展”。英语早期也能中性地说结果，后来“好结果”占了主流。',SUCCESS,'现代说 success 通常是达到目标。success 不加冠词可谈成功这件事；a success 则把某个人、活动或作品当成成功的例子。','achieve success；a great success；success in doing…。','success 说结果如愿；succession 说一个接一个，后者不保证结果好。',('The event was a success despite the rain.','虽然下雨，活动仍办得很成功。'),('Her success came after years of practice.','她经过多年练习才取得成功。'),sources=['https://www.etymonline.com/word/success','https://en.wiktionary.org/wiki/success#English']),
E('successful','/səkˈsesfəl/','成功的；达到目的的','把要办的事办成了。','success + -ful；-ful 在这里表示具有成功结果。',SUCCESS+[['英语 success + -ful → successful','取得预期结果的']],'successful repair 是修好了；successful application 是申请获准。形容人时常指事业或工作有成，但不必理解为有钱才成功。','a successful attempt；successful in doing…。','successive 是接连发生的；successful 才是成功的，拼写相近而重点不同。',('The team made a successful landing on the test field.','团队在试验场完成了成功的着陆。'),('She was successful in finding a new supplier.','她成功找到了新的供应商。')),
E('procedure','英 /prəˈsiːdʒə/；美 /prəˈsiːdʒər/','程序；操作步骤；医疗操作','事情要往前办，先有一条按什么顺序走的路线。','借法语 procédure，源于 prōcēdere“向前推进”；现代不能简单当成英语 proceed 加一个现成后缀。',PROCEDURE,'程序关注“先做什么，再做什么”。a medical procedure 可以是检查或治疗操作，未必都是外科手术；操作的具体内容由上下文交代。','follow a procedure；standard procedure；a medical procedure。','process 可说事情怎样发展；procedure 更常说该按什么步骤操作。',('Please follow the procedure for returning damaged goods.','请按退还受损商品的程序办理。'),('The nurse explained the procedure before it began.','护士在操作开始前解释了步骤。')),
E('succeed','/səkˈsiːd/','成功；接替；随后出现','一件事接着发展，或一个人接着另一个人上场。','拉丁 sub-“随后、接近” + cēdere；经古法语 succeder 并受拉丁词影响进入英语。',SU+[['古法语 succeder／拉丁 succēdere → 中古英语 succeden','接替、继承；进展顺利'],['英语 succeed','接任；成功']],'succeed in doing 是成功做成；succeed someone 是接替某人。She succeeded him 不表示她战胜了他，而是她接了他的职位。','succeed in doing；succeed someone as…；succeed to the throne。','succeed 的“接替”义不自带“更优秀”；下一任可能干得好，也可能不好。',('We succeeded in repairing the old radio.','我们成功修好了旧收音机。'),('Maya succeeded Daniel as team leader.','玛雅接替丹尼尔担任组长。')),
E('proceed','/prəˈsiːd/','继续；接着做；前往','脚步或事情已经有了方向，接着往前走。','拉丁 prō-“向前” + cēdere；经法语及拉丁借入，成为中古英语 proceden。',PROCEED,'proceed with a plan 是继续执行计划；proceed to do 是接着做下一件事。广播中 proceed to Gate 4 就是前往四号登机口。','proceed with；proceed to；proceed cautiously。','precede 是在前，proceed 是向前继续。先后顺序和继续动作要分开。',('After a short break, we proceeded with the discussion.','短暂休息后，我们继续讨论。'),('Passengers should proceed to Gate Four.','旅客请前往四号登机口。')),
E('preceding','/prɪˈsiːdɪŋ/','前面的；紧接在之前的','沿着顺序回头看，指出已经排在前面的那一项。','precede 的 -ing 形式；作形容词的用法在中古英语 precedyng 等形式中已经存在。',PRE+[['中古英语 preceden → precedyng / precedenge','在前 → 位于前面的'],['英语 preceding','前述的、前一个阶段的']],'the preceding paragraph 是前面的那段；the preceding year 通常是相对于文中时间的上一年，不一定是现在的去年。','the preceding chapter；the preceding day；the preceding discussion。','previous 可宽泛说以前的；preceding 更强调相对某项的位置和顺序。',('The answer appears in the preceding paragraph.','答案在前一段中。'),('Sales were higher than in the preceding year.','销售额高于前一年。')),
E('procession','/prəˈseʃən/','队列；列队行进；一连串经过的人或事','大家按一个方向陆续向前走，形成一条移动的长队。','借法语及拉丁 prōcessiō“向前行进”；词族来自 prōcēdere，不是现代英语 process 加 -ion 才首次造出。',PROCESSION,'通常有仪式感，比如婚礼、葬礼或庆典队伍；也可说 a procession of visitors，来访者一拨接一拨。','a funeral procession；a procession of；join the procession。','process 是过程；procession 主要是行进队列。两者都含“向前”，却不能互换。',('The procession moved slowly through the village.','队伍缓缓穿过村庄。'),('A procession of visitors passed through the gallery.','一拨接一拨的参观者经过展厅。'),sources=['https://www.etymonline.com/word/procession','https://en.wiktionary.org/wiki/procession#English']),
E('procedural','英 /prəˈsiːdʒərəl/；美 /prəˈsiːdʒərəl/','程序上的；按程序进行的；重办案过程的侦探作品','把镜头对准事情如何一步步办理。','procedure + -al；名词用法常省略 police procedural 等短语后的 novel、drama。',PROCEDURE+[['英语 procedure + -al → procedural','与办理步骤有关；强调办案程序的作品']],'procedural error 指流程或办理方式出错，不一定说明最终内容判断错了。a police procedural 常写警员调查、取证、协作的具体过程。','procedural rules；a procedural error；a police procedural。','substantive 关注事情本身的实质；procedural 关注如何处理。',('The application was delayed by a procedural error.','申请因程序上的错误而延误。'),('She enjoys police procedurals that show how evidence is collected.','她喜欢描写取证过程的警察办案小说。')),
E('concede','/kənˈsiːd/','承认；让步；认输；丢分','原来守住的一块，现在让给对方。','拉丁 con- 加强 + cēdere“让出”；经法语 conceder / concéder，亦有直接拉丁借入分析。',CO+[['法语 conceder / concéder 及拉丁词 → 英语 concede','让步、承认、给予']],'争论中 concede a point 是承认对方这一点成立；比赛中 concede a goal 是被对手进球，不暗示故意放水。concede defeat 则是承认落败。','concede that…；concede a point；concede defeat；concede a goal。','admit 可以很中性地承认；concede 常带“本来不愿意，但退让了”的感觉。',('I concede that your plan is cheaper.','我承认你的方案更便宜。'),('The team conceded two goals before halftime.','球队在半场结束前丢了两个球。'),sources=['https://www.etymonline.com/word/concede','https://en.wiktionary.org/wiki/concede#English']),
E('precedence','常用 /ˈpresɪdəns/；也读 /prɪˈsiːdəns/','优先；在先；先后次序','几件事排队时，谁有资格排到前面。','可联系 precede 与 -ence；词典另列法语 précédence、中世纪拉丁 praecedentia，或英语 precedent 改接 -ence 的分析。',PRE+[['法语 précédence／中世纪拉丁 praecedentia；亦有英语 precedent + -ence 分析','在先的状态、顺序'],['英语 precedence','优先权、优先次序']],'take precedence over… 是比……优先。运算里的 operator precedence 决定先算乘法还是加法；礼仪场合也可谈席位和尊卑次序。','take precedence over；give precedence to；operator precedence。','precedent 是一个可援引的先例；precedence 是优先关系。通常说 set a precedent，不说 set a precedence。',('Safety takes precedence over speed.','安全优先于速度。'),('Multiplication has precedence over addition in this expression.','这个表达式中先做乘法，再做加法。'),sources=['https://www.merriam-webster.com/dictionary/precedence','https://www.etymonline.com/word/precedence','https://en.wiktionary.org/wiki/precedence#English']),
E('cede','/siːd/','让出；割让；移交','把自己原来掌握的东西交到别人手里。','借法语 ceder，直接上接拉丁 cēdere“走开、让出”。',H+[['法语 ceder → 英语 cede','让出权利、地位、控制或领土']],'常见宾语是 control、power、territory。不是普通的把杯子递过去，而是把控制权或所有权交出去。','cede control to；cede power；cede territory。','concede 可承认一个观点，也可让步；cede 更直接说把某项权力或资产让出。',('The founder ceded control of the company to a new team.','创始人把公司的控制权交给了新团队。'),('Neither side was willing to cede the disputed territory.','双方都不愿让出争议领土。')),
E('precede','/prɪˈsiːd/','在……之前；先于','站到某件事前面，时间或顺序都可以。','拉丁 prae-“在前” + cēdere；经中古法语 précéder 进入英语。',PRECEDE,'A precedes B 就是 A 在 B 前面。be preceded by 把视角反过来：The talk was preceded by a film，是先放电影再演讲。','precede something；be preceded by；immediately precede。','proceed 是继续进行；precede 只交代相对顺序，不一定是因果关系。',('A short introduction will precede the main talk.','正式演讲前会有一段简短介绍。'),('The storm was preceded by an unusual silence.','暴风雨来临前，四周异常安静。')),
E('secede','/sɪˈsiːd/','退出；脱离〔国家、联盟等〕','原来一起走，现在分出去另走一条路。','直接借拉丁 sēcēdere；sē- 是“分开”，cēdere 是“走”。',SE+[['英语 secede','从政治共同体或组织中退出']],'常见于一个地区、成员或团体退出较大的政治组织。它强调脱离关系，不是单纯搬家或暂时离开会场。','secede from；vote to secede。','recede 是退回、退去；secede 是退出原来的共同体。',('The province voted to secede from the federation.','该省投票决定脱离联邦。'),('Several members threatened to secede from the association.','几个成员威胁要退出协会。')),
E('recede','/rɪˈsiːd/','退去；后退；逐渐减弱','原来靠近眼前的边缘，慢慢往后撤。','拉丁 re-“向后” + cēdere；经中古法语 receder 及拉丁词进入中古英语 receden。',RE+[['中古法语 receder／拉丁 recēdere → 中古英语 receden → 英语 recede','向后退；潮水、声音、记忆等渐远']],'潮水退去是最直观的画面。发际线后移、远去的脚步声、渐淡的恐惧，也都可用。recede 通常是不及物动词。','the tide recedes；a receding hairline；recede into the distance。','retreat 常有主动撤退的意味；recede 也能描述自然退去和逐渐减弱。',('The floodwater began to recede overnight.','洪水在夜间开始退去。'),('The sound of the train receded into the distance.','火车声渐渐消失在远处。')),
E('accede','/əkˈsiːd/','同意〔请求等〕；加入；就任','往一个请求、协议或职位那里走，正式接下它。','拉丁 ad-“朝向” + cēdere；ad- 在 c 前同化为 ac-，成为 accēdere，再借入中古英语 acceden。',AC+[['中古英语 acceden → 英语 accede','同意；进入职位或加入协议']],'accede to a request 是同意请求；accede to the throne 是即位；accede to a treaty 是成为条约参加方。常需要 to。','accede to a request；accede to a treaty；accede to the throne。','agree 更日常；accede 较正式，常有接受既有请求、条件或地位的意味。',('The committee acceded to the request for more time.','委员会同意了延长时间的请求。'),('She acceded to the throne at a young age.','她年轻时就登上了王位。')),
E('processional','/prəˈseʃənəl/','行列的；入场曲；仪式队列','给正式行进的队伍用的，或队伍行进时演奏的。','现代按 procession + -al 理解；既可作形容词，也可把供行进用的乐曲称为 a processional。',PROCESSION+[['英语 procession + -al → processional','列队行进相关；供队列使用的乐曲、礼仪内容等']],'婚礼的 processional music 是入场时的音乐。作为名词也能说仪式队伍，或旧时收录游行仪式材料的书。','processional music；a processional route；play a processional。','procedural 谈办理程序；processional 谈行进队列。',('The organist began the processional as the doors opened.','门打开时，管风琴师奏起了入场曲。'),('Flowers lined the processional route.','鲜花沿仪式队伍的行进路线摆放。'),sources=['https://www.merriam-webster.com/dictionary/processional','https://en.wiktionary.org/wiki/processional#English']),
E('successfully','/səkˈsesfəli/','成功地；顺利地','动作做完，而且达到了预期效果。','successful + -ly。',SUCCESS+[['英语 success → successful → successfully','成功 → 成功的 → 成功地']],'successfully installed 表示安装完成并达到要求。它评价结果，不必说过程轻松：可以经历很多失败后才 successfully complete。','successfully complete；successfully install；successfully apply。','easily 是不费力；successfully 是办成了，艰难完成也可以成功。',('The update was successfully installed.','更新已成功安装。'),('They successfully crossed the river before sunset.','他们在日落前成功渡过了河。')),
E('unsuccessful','/ˌʌnsəkˈsesfəl/','未成功的；没有达到目的的','试过了，但没有抵达想要的结果。','un-“不” + successful。',SUCCESS+[['英语 successful → unsuccessful','成功的 → 未成功的']],'an unsuccessful attempt 是一次没有成功的尝试，不代表人永远无能。正式邮件里 an unsuccessful application 常是申请未获批准。','an unsuccessful attempt；unsuccessful in doing…。','failed 常更直接；unsuccessful 较中性地说明结果没达成。',('Our first attempt was unsuccessful.','我们第一次尝试没有成功。'),('The applicant was unsuccessful but asked for feedback.','申请人未能获选，但请求了反馈意见。')),
E('succession','/səkˈseʃən/','连续；一连串；继承；接任','前一个刚过去，后一个就跟上来。','借法语 succession，接拉丁 successiō“接着来”，与 succēdere 同族。',SU+[['拉丁 successiō → 古法语 succession → 中古英语、英语 succession','接续；继承与接任']],'in quick succession 是接连迅速发生；succession to the throne 是王位继承。生态学也用 succession 说一个地方的群落随时间被后续群落替换。','a succession of；in rapid succession；a succession plan。','success 是成功；succession 是接续。a succession of failures 就是一连串失败。',('Three buses arrived in quick succession.','三辆公交车接连到站。'),('The company has no clear succession plan.','公司没有明确的接班计划。')),
E('successive','/səkˈsesɪv/','连续的；接连的；相继的','这一项之后紧接着下一项，中间按顺序走。','经法语 successif 或中世纪拉丁 successivus 借入；基础是 succēdere“接着来”，现代可认出 success- 与 -ive。',SU+[['中世纪拉丁 successivus／古法语 successif → 英语 successive','一个接一个的']],'three successive days 是连续三天。successive governments 是前后各届政府，不是在夸每届政府都成功。','successive generations；three successive wins；successive stages。','successful 表示成功；successive 表示接连。three successive defeats 是三连败。',('It rained on five successive days.','一连五天都下雨。'),('Successive managers tried to solve the same problem.','前后几任经理都试图解决同一个问题。'),sources=['https://www.etymonline.com/word/successive','https://en.wiktionary.org/wiki/successive#English']),
E('successor','英 /səkˈsesə/；美 /səkˈsesər/','继任者；接替者；后继型号','前一个位置空出来，由它接着坐上去。','借盎格鲁法语 successour，接拉丁 successor；不是从现代“成功”义 success 推出“成功者”。',SU+[['拉丁 successor → 盎格鲁法语 successour → 英语 successor','接替前任的人或事物']],'职位可以有 successor，旧电脑型号也可以有 successor。successor to someone 说某人的继任者。','a successor to；name a successor；the successor model。','predecessor 是前任；successor 是后任。winner 才是获胜者。',('The board named her successor before she retired.','董事会在她退休前就指定了继任者。'),('This camera is the successor to last year’s model.','这款相机是去年那款的后继型号。')),
E('process','名词及“处理”动词：英 /ˈprəʊses/；美 /ˈprɑːses/；“列队行进”动词 /prəˈses/','过程；程序；处理；加工；列队行进','事物一步步往前变化；处理它，就是让它走过所需步骤。','常用名词来自法语 proces 和拉丁 prōcessus；“处理”动词由名词发展。重音在后的“列队行进”动词则从 procession 逆构。',PROCESS+[['英语名词 → process“处理”；另一路 procession → process“列队行进”','两种动词的形成与重音不同']],'a learning process 是学习过程；process an application 是受理并处理申请。解剖学的 process 还能指突起，是“向外伸出”的专门义。重音在后的 process 较少见，别套到电脑处理数据上。','a gradual process；process data；process an application。','procedure 常是规定的操作步骤；process 可以包括自然发生的变化。proceed 是继续，不是“处理某物”。',('Learning a language is a gradual process.','学习语言是一个渐进过程。'),('The office will process your application this week.','办公室本周会处理你的申请。'),('The choir will process into the hall after the bell.','铃响后，合唱团将列队进入大厅。'),sources=['https://www.etymonline.com/word/process','https://en.wiktionary.org/wiki/process#English']),
E('processing','英 /ˈprəʊsesɪŋ/；美 /ˈprɑːsesɪŋ/','处理；加工；处理中的','材料或信息正在经过一连串步骤，变成可用的结果。','process 的 -ing 形式，常用为名词；此处沿“处理、加工”动词路线，重音在首音节。',PROCESS+[['英语 process“处理” + -ing → processing','处理过程或加工过程']],'food processing 是食品加工；image processing 是图像处理；payment processing 是办理付款。这个词本身不评价处理方式是好是坏。','data processing；food processing；processing time。','processed 强调已经处理后的状态；processing 强调正在进行的处理或处理这项活动。',('Image processing removed the background noise.','图像处理去除了背景噪点。'),('The form shows the expected processing time.','表格上列出了预计办理时间。')),
E('proceeds','名词：英 /ˈprəʊsiːdz/；美 /ˈproʊsiːdz/；proceed 的动词形式 /prəˈsiːdz/','所得款；收入；〔动词〕继续','交易或活动往前做完后，产生出来的那笔钱。','从 proceed“由……产生”形成名词，后常用复数 proceeds；动词 proceeds 只是 proceed 的第三人称单数。',PROCEED+[['英语 proceed“产生” → 名词 proceed / proceeds','由活动或销售产生的款项']],'the proceeds from a sale 是销售所得；不加 net 时不能自动当成扣完成本的净利润。名词重音在前，The meeting proceeds 的动词重音在后。','the proceeds from；donate the proceeds；net proceeds。','profit 明确关注收入扣去成本后的利润；proceeds 可说所得款项，是否扣费要看 gross、net 等限定。',('The proceeds from the concert went to the library.','音乐会所得款项捐给了图书馆。'),('The charity received the net proceeds after expenses.','慈善机构收到了扣除费用后的净收入。'),sources=['https://www.etymonline.com/word/proceeds','https://en.wiktionary.org/wiki/proceeds#English']),
E('concession','/kənˈseʃən/','让步；承认；优惠；特许经营权或摊点','本来握在手里的东西，让出一点给别人。','借法语 concession，接拉丁 concessiō，来自 concēdere“让出、允许”；现代可以认出 concess- 与 -ion。',CO+[['拉丁 concessiō → 中古法语 concession → 英语 concession','给予、允许、让步']],'谈判中的 concession 是退让；票价 concession 是给某类人的优惠。经营 concession 则是获准在某处营业的权利，继而也能指获准经营的摊点。','make a concession；price concessions；a concession stand。','compromise 常是双方协调后达成的安排；concession 可以只是一方作出的一次退让。',('Both sides made concessions to reach an agreement.','双方都作了让步以达成协议。'),('The museum offers concessions for students.','博物馆为学生提供票价优惠。'),('We bought popcorn at the concession stand.','我们在场内售卖亭买了爆米花。')),
E('precedent','名词 /ˈpresɪdənt/；较正式形容词 /prɪˈsiːdənt/','先例；前例；在先的〔形容词〕','前面已经发生过的一次，可以拿来给后面的事作参照。','借法语 precedent 与拉丁 praecēdēns“走在前面的”；英语从“在先的”进一步发展出“先例”名词。',PRECEDENT,'set a precedent 是开一个先例；follow a precedent 是照先例办。法律里的 precedent 是可供后续类似案件参照的裁判，具体约束力取决于法律体系及层级。','set a precedent；follow a precedent；without precedent。','precedence 是优先次序；precedent 是先前的例子。precedent 的名词与形容词还会换重音。',('Allowing one exception could set a precedent.','允许一次例外可能会开先例。'),('The judge discussed a relevant precedent.','法官讨论了一个相关判例。'),sources=['https://www.etymonline.com/word/precedent','https://en.wiktionary.org/wiki/precedent#English']),
E('unprecedented','/ʌnˈpresɪdentɪd/','前所未有的；史无前例的','往前翻记录，找不到能相比的先例。','un-“没有” + precedent“先例” + -ed“具有……的”。',PRECEDENT+[['英语 un- + precedent + -ed → unprecedented','没有相应先例的']],'通常说规模、程度或情况超出此前经验，不必声称全宇宙从来没出现过。应理解为在谈论的范围内没有先例。','an unprecedented level；unprecedented demand；an unprecedented decision。','unusual 只是少见；unprecedented 的说法更强，强调没有先例。',('The exhibition attracted an unprecedented number of visitors.','展览吸引了空前多的参观者。'),('The city faced an unprecedented shortage of water.','这座城市面临前所未有的缺水状况。')),
E('recession','/rɪˈseʃən/','衰退；退缩；后退','原本向前的范围或活动，现在往回缩。','接拉丁 recessiō“后退”，可经法语 récession 或直接借入；经济义是较后发展的用法。',RE+[['拉丁 recessiō／法语 récession → 英语 recession','退去、后退'],['英语经济用法 recession','经济活动明显下滑的一段时期']],'最常见于经济新闻，表示经济活动收缩，不能仅当成某一家店生意不好。也能指冰川或牙龈等边缘退缩；这些义都保留“往后退”。','an economic recession；enter a recession；glacial recession。','recession 常是经济或实体的退缩；regression 更宽泛说退回较早状态，也有统计学专义。',('Many firms reduced hiring during the recession.','经济衰退期间，许多公司减少了招聘。'),('The photographs document the recession of the glacier.','这些照片记录了冰川的退缩。'),sources=['https://www.etymonline.com/word/recession','https://en.wiktionary.org/wiki/recession#English']),
E('recess','英常读 /rɪˈses/；美名词常读 /ˈriːses/，动词也读 /rɪˈses/','休会；课间休息；凹处；使凹入','时间上先退出来歇一会儿，空间上则往里面退一块。','名词借拉丁 recessus“退去、隐蔽处”，也受法语 recès 影响；英语再由名词形成动词。',RE+[['拉丁 recessus → 英语 recess，受法语 recès 影响','退去、隐处 → 休会、凹处'],['英语名词 recess → 动词 recess','暂时休会；把东西嵌入凹处']],'学校里的 recess 是课间休息；议会或法庭的 recess 是暂时休会、休庭。a recess in the wall 则是墙上的凹位，像墙面往后让了一步。','during recess；in recess；a wall recess；recessed lighting。','break 是普通的暂停；recess 还带机构休会和空间凹处两组常用义。',('The children played outside during recess.','孩子们在课间休息时到外面玩。'),('A small lamp stood in a recess in the wall.','墙上的凹位里放着一盏小灯。')),
E('secession','/sɪˈseʃən/','退出；脱离；分离','把原本连在一起的政治或组织关系断开。','借拉丁 sēcessiō“离开、退出”，来自 sēcēdere；现代能认出 secess- 与 -ion，但名词有独立借入路线。',SE+[['拉丁 sēcessiō → 英语 secession','退出共同体的行为']],'常用于地区脱离国家、成员退出联盟的讨论，语气比普通 departure 更政治化。字中是 se-，不是 succession 的 suc-。','secession from；a secession movement；oppose secession。','succession 是接班、接续；secession 是分离、退出。',('The debate focused on the proposed secession of the region.','辩论围绕该地区拟议中的分离展开。'),('The association changed its rules after the secession of several members.','几名成员退出后，协会修改了规则。')),
E('access','/ˈækses/','进入或使用的机会、权利；通道；访问、获取','能够走到它那里，再接触或使用它。','接拉丁 accessus“走近、通路”，可经法语 acces 或直接借入；现代“访问”动词由名词发展。',AC+[['拉丁 accessus／法语 acces → 中古英语 acces / accesse','接近、进入；早期也说发作'],['英语 access 名词 → 动词','进入机会、通道 → 访问、获取']],'have access to a library 是能使用图书馆，不一定拥有它；access a file 是打开或读取文件。名词常带 to，动词直接接宾语。','have access to；gain access；access a database。','accede to 是正式同意、加入或就位；access 是能够接近或使用。不能把 access to 当成所有动词场景的固定组合。',('Students have free access to the archive.','学生可以免费使用档案库。'),('You can access the document from your phone.','你可以通过手机访问这份文档。')),
E('accession','/ækˈseʃən/','就任；即位；加入；新增藏品；登记入藏','走进一个职位或共同体；一件物品也可新加入收藏。','借拉丁 accessiō“靠近、加入、增加”，接 accēdere；不是 access 的现代动词加 -ion 才首次造出。',AC+[['拉丁 accessiō → 英语 accession','加入、增加；登上职位'],['英语 accession 作收藏术语','新增藏品或正式登记入藏']],'accession to the throne 是即位；an accession number 是新藏品的登记号。作动词时，馆员 accession an object 是把物品纳入正式馆藏记录。','accession to；an accession number；new accessions。','access 强调使用和进入的机会；accession 常指正式加入、就任或入藏这件事。',('The coin commemorates the queen’s accession to the throne.','这枚硬币纪念女王即位。'),('Each new object receives an accession number.','每件新藏品都会获得一个入藏编号。'),sources=['https://www.etymonline.com/word/accession','https://en.wiktionary.org/wiki/accession#English']),
E('cease','/siːs/','停止；终止','原来的动作退下去，不再继续。','经法语 cesser、拉丁 cessāre，属于 cēdere 的反复动词支线；它的常用义已经定为停止。',CEASE,'cease trading 是停止营业；cease to exist 是不复存在。语气比 stop 正式。这里没有让出所有权的意思，也不要与 seize“抓住”混读。','cease to do；cease doing；cease operations。','cease 读清音 /s/ 结尾；seize 读浊音 /z/，意思是抓取、夺取。',('The factory ceased production last winter.','工厂在去年冬天停产了。'),('The old system has ceased to be useful.','旧系统已经不再有用了。')),
E('cessation','/seˈseɪʃən/','停止；中断；终止','把一直在进行的事画上暂停或结束线。','借法语 cessation，接拉丁 cessātiō，来自 cessāre“停止”；与 cease 同支，区别于 cession“让与”。',H+[['拉丁 cessāre → cessātiō → 法语 cessation','停止 → 停止这一行为'],['英语 cessation','某种活动的停止或中断']],'通常较正式，说明什么活动停止了；temporary cessation 是暂时中断，所以单词本身不保证永远不再发生。','cessation of；temporary cessation；a complete cessation。','cession 是把领土或权利让给别人；cessation 是让活动停下来，多出的 -at- 对应不同拉丁构词支线。',('The agreement called for a cessation of hostilities.','协议要求停止敌对行动。'),('Repairs required a temporary cessation of production.','维修需要暂时停产。'))
]
m=json.loads((BASE/'.cache/batch200/rewrite_spec.json').read_text());family=next(r['family'] for r in m['roots'] if r['id']=='C0189')
R=[dict(id='C0189',meaning='走；退让；接续',core='往某个方向走，或给别人让出位置',image='几个人在路上：往前走是 proceed，先走在前是 precede，退回是 recede，让出位置是 cede，下一位接上是 succeed。',intro='拉丁 cēdere 的动作不复杂：走、离开、让步。前缀改变方向，英语词义再向事务、权利和结果延伸。cess- 是同族的词干形式，不等于所有这些词都先在英语里由 cede 拼出来。多数名词和形容词各自经法语或拉丁语借入。',forms='proceed、succeed 用 -ceed，precede、recede、concede 等用 -cede；success、process、access 等保留 cess- 形式。cease、cessation 经 cessāre“停止”的支线。process 与 proceeds 还需注意词义不同带来的重音变化。',branches=[['向前推进','proceed、procedure、procedural、process、processing、procession、processional、proceeds'],['前后次序','precede、preceding、precedent、precedence、unprecedented'],['接续与成功','succeed、success、successful、successfully、unsuccessful、succession、successive、successor'],['让出与退出','cede、concede、concession、secede、secession'],['退回与停止','recede、recession、recess、cease、cessation'],['走近与加入','accede、access、accession']],contrasts='success 是成功，succession 是接续，secession 是退出；precede 是在前，proceed 是继续；precedent 是先例，precedence 是优先关系。词根帮助看懂方向，最后仍要按每个词真实的搭配使用。',practice='用一条职位交接的小故事串起 predecessor、succeed、successor、succession，再说明为什么一位 successor 不一定 successful。将“先放电影，再继续讨论”分别用 precede 和 proceed 表达。',words=list(family),sources=['https://www.etymonline.com/word/success','https://www.etymonline.com/word/process','https://en.wiktionary.org/wiki/cede#English'])]
assert {w['word'] for w in W}==set(family),set(family)-{w['word'] for w in W}
for w in W:
 assert len(w['examples'])>=2 and len(w['history'])>=2 and w['ipa']
 assert all(len(n)==2 and all(isinstance(v,str) and v for v in n) for n in w['history'])
for k,d in [('roots',R),('words',W)]: (OUT/f'{k}_batch200_spec_13_ced.json').write_text(json.dumps(d,ensure_ascii=False,indent=2))
print('C0189',len(W),'new',sum(len(w['examples']) for w in W),'examples')
